# New approach: for each color, place cells around the center
import math

def create_centered_arrangement(colors_positions, grid_size=7, center=(3,3)):
    result = [[0]*grid_size for _ in range(7)]

    for color, pos in sorted(colors_positions.items()):
        # For each color, place cells in order touching the center
        # Use Manhattan distance from center as "slots"
        distances = []
        for r in range(grid_size):
            for c in range(grid_size):
                d = abs(r - center[0]) + abs(c - center[1])
                distances.append((d, r, c))

        # Sort by distance
        distances.sort()

        # Fill from the center outward
        for i, (d, r, c) in enumerate(distances):
            if i < len(pos):
                result[r][c] = color
            else:
                break

    return result

