def classify_grid(results):
    primary, secondary, confidence = 'unknown', 'unknown', 0.0
    orientations = results.get('line_orientations', [])
    is_bidirectional = len(set(orientations)) >= 2

    if not orientations:
        primary, confidence = 'no_lines', 0.95
    elif all(d == 0 for d in set(orientations)):
        primary, confidence = 'horizontal', 0.95
    elif all(d == 90 for d in set(orientations)):
        primary, confidence = 'vertical', 0.95
    elif all(d == 45 or d == 135 for d in set(orientations)):
        primary, confidence = 'diagonal', 0.9
    elif len(set(orientations)) <= 2:
        primary, confidence = 'mixed', 0.7
    else:
        primary = f'custom_{np.median(orientations)}'
        confidence = 0.7

    if is_bidirectional:
        secondary = 'square_grid'
        confidence = max(confidence, 0.95)
    elif len(set(orientations)) == 1:
        if sum(1 for d in orientations if d == 0) > 3:
            secondary, confidence = 'parallel_horizontal', 0.92
        elif sum(1 for d in orientations if d == 90) > 3:
            secondary, confidence = 'parallel_vertical', 0.92
        else:
            secondary, confidence = 'sparse_parallel', 0.6
    else:
        secondary, confidence = 'irregular', 0.5

    point_count = results.get('point_count', 0)
    if point_count > 100:
        tertiary = 'dense'
    elif point_count > 10:
        tertiary = 'moderate'
    else:
        tertiary = 'sparse'

    return {'primary': primary, 'secondary': secondary, 'tertiary': tertiary, 'confidence': round(confidence, 3)}


