import json

def fill_triangle_cells(cells, output_size=7, fill_order='row'):
    """
    Fill the triangle r+c < size into a grid.
    fill_order: 'row', 'col', or 'spiral'
    """
    grid = [[0]*output_size for _ in range(output_size)]

    if fill_order == 'row':
        idx = 0
        for r in range(output_size):
            for c in range(output_size):
                if r + c < output_size and idx < len(cells):
                    grid[r][c] = cells[idx]
                    idx += 1

    elif fill_order == 'col':
        idx = 0
        for c in range(output_size):
            for r in range(output_size):
                if r + c < output_size and idx < len(cells):
                    grid[r][c] = cells[idx]
                    idx += 1

    elif fill_order == 'spiral':
        r, c = 0, 0
        idx = 0
        while idx < len(cells):
            if r + c < output_size:
                grid[r][c] = cells[idx]
                idx += 1
            if r == 0 and c < output_size - 1:
                c += 1
            elif c == output_size - 1 and r < output_size - 1:
                r += 1
            elif r == output_size - 1 and c > 0:
                c -= 1
            elif c == 0 and r > 0:
                r -= 1
            else:
                r += 1
                c += 2
                if r + c >= output_size:
                    r = 0
                    c = 0
    return grid

